const fs = require('fs');

function main() {
    const input = fs.readFileSync('/dev/stdin', 'utf8').trim().split(/\s+/).map(Number);
    if (input.length === 0) return;

    let idx = 0;
    const n = input[idx++];
    const ara = [];

    for (let i = 0; i < n; i++) {
        ara.push([
            input[idx++],
            input[idx++],
            input[idx++],
            input[idx++]
        ]);
    }

    let f = 0;
    for (let i = 0; i < n; i++) {
        const s = Math.abs(ara[i][0] - ara[i][2]);
        const t = Math.abs(ara[i][1] - ara[i][3]);
        f += s * t;
    }

    let mini = 100000;
    let min = 100000;
    let maxi = 0;
    let max = 0;

    for (let i = 0; i < n; i++) {
        if (ara[i][0] < mini) mini = ara[i][0];
        if (ara[i][1] < min) min = ara[i][1];
        if (ara[i][2] > maxi) maxi = ara[i][2];
        if (ara[i][3] > max) max = ara[i][3];
    }

    const w = (maxi - mini) * (max - min);

    if (f === w && (maxi - mini) === (max - min)) {
        console.log("YES");
    } else {
        console.log("NO");
    }
}

